insert into public.recipes (slug, title, description, storage_note, servings, prep_minutes,
  cook_minutes, tags, status, source, source_ref, validated_at)
select v.slug, v.title, v.description, v.storage, v.servings, v.prep, v.cook, v.tags,
  'published', 'curated', 'Aux Petits Oignons — recette originale', now()
from (values
  ('raclette-au-four-pommes-de-terre-jambon-cru', 'Raclette au four, pommes de terre et jambon cru', 'Toute la raclette sans appareil : des pommes de terre grenaille fondantes couvertes de fromage à raclette gratiné au four, avec du jambon cru, des cornichons et une salade.', 'À manger tout de suite ; les pommes de terre cuites se gardent 3 jours au réfrigérateur.', 2, 10, 35, array['plat', 'four']::text[]),
  ('tartiflette-reblochon-lardons', 'Tartiflette au reblochon et aux lardons', 'Le grand classique savoyard : des pommes de terre, des lardons et des oignons fondus à la crème, sous un reblochon entier qui gratine au four.', 'Se garde 3 jours au réfrigérateur ; réchauffer au four.', 4, 20, 50, array['plat', 'four', 'batch-cooking']::text[]),
  ('mont-d-or-chaud-pommes-de-terre', 'Mont d''or chaud au four, pommes de terre et jambon cru', 'Une boîte de mont d''or chauffée au four avec un trait de vin blanc, à partager en y trempant des pommes de terre et du jambon cru. Le plat des soirées d''hiver.', 'À manger tout de suite ; le reste de fromage se garde 2 jours au réfrigérateur et se réchauffe au four.', 3, 10, 30, array['plat', 'four']::text[]),
  ('truffade-cantal-lardons', 'Truffade au cantal et aux lardons', 'Des pommes de terre rissolées à la poêle avec de l''ail et des lardons, liées par du cantal fondu qui file. Une recette auvergnate pour les soirs froids.', 'À manger de préférence tout de suite ; se garde 2 jours au réfrigérateur.', 2, 15, 30, array['plat', 'poele']::text[]),
  ('risotto-champignons-beaufort', 'Risotto aux champignons et au beaufort', 'Un risotto crémeux aux champignons de Paris, au vin blanc et au bouillon, lié au beaufort râpé à la fin de la cuisson.', 'Se garde 2 jours au réfrigérateur ; réchauffer avec un peu de bouillon.', 2, 10, 25, array['plat', 'mijote']::text[]),
  ('gratin-chou-fleur-gruyere-jambon', 'Gratin de chou-fleur au gruyère et jambon', 'Des bouquets de chou-fleur et des dés de jambon nappés d''une béchamel au gruyère, gratinés au four jusqu''à être bien dorés.', 'Se garde 3 jours au réfrigérateur ; réchauffer au four.', 2, 15, 30, array['plat', 'four', 'economique']::text[]),
  ('gratin-poireaux-mimolette-jambon', 'Gratin de poireaux à la mimolette et au jambon', 'Des poireaux fondants roulés dans du jambon, nappés d''une béchamel à la mimolette qui gratine en une croûte orangée.', 'Se garde 3 jours au réfrigérateur ; réchauffer au four.', 2, 15, 30, array['plat', 'four', 'economique']::text[]),
  ('camembert-roti-pommes-de-terre-jambon-cru', 'Camembert rôti, pommes de terre et jambon cru', 'Un camembert entier rôti au four avec de l''ail et du thym, dans lequel on trempe des pommes de terre grenaille et des lamelles de jambon cru. Avec une salade de mâche.', 'À manger tout de suite.', 2, 10, 30, array['plat', 'four']::text[]),
  ('flamiche-maroilles-poireaux', 'Flamiche au maroilles et aux poireaux', 'Une tarte du Nord aux poireaux fondus, garnie d''un appareil aux œufs et à la crème et de tranches de maroilles qui fondent à la cuisson.', 'Se garde 2 jours au réfrigérateur ; réchauffer au four.', 4, 20, 35, array['plat', 'four']::text[]),
  ('pommes-de-terre-farcies-munster-jambon', 'Pommes de terre farcies au munster et au jambon', 'De grosses pommes de terre évidées, garnies de leur chair écrasée avec du jambon et du cumin, couvertes de munster et gratinées au four.', 'Se garde 2 jours au réfrigérateur ; réchauffer au four.', 2, 15, 45, array['plat', 'four']::text[]),
  ('feuillete-brie-poireaux', 'Tarte feuilletée au brie et aux poireaux', 'Une pâte feuilletée garnie de poireaux fondus, d''un œuf battu à la crème et de tranches de brie, cuite jusqu''à ce que le feuilletage soit croustillant.', 'Se garde 2 jours au réfrigérateur ; réchauffer au four pour garder le croustillant.', 2, 15, 25, array['plat', 'four']::text[]),
  ('pates-gorgonzola-epinards-noix', 'Pâtes au gorgonzola, épinards et noix', 'Des pâtes nappées d''une sauce onctueuse au gorgonzola fondu dans la crème, avec des épinards et des noix concassées pour le croquant.', 'Se garde 2 jours au réfrigérateur ; réchauffer avec un peu de lait.', 2, 5, 15, array['plat', 'poele']::text[]),
  ('salade-endives-poulet-roquefort-noix', 'Salade d''endives, poulet, roquefort et noix', 'Une salade d''hiver croquante : endives, poire, poulet doré, roquefort émietté et noix, avec une vinaigrette à la moutarde.', 'Se garde 2 jours au réfrigérateur, vinaigrette à part ; ajouter la poire au dernier moment.', 2, 15, 8, array['salade', 'plat', 'lunch-box']::text[]),
  ('gnocchis-fourme-ambert-poire-noix', 'Gnocchis à la fourme d''Ambert, poire et noix', 'Des gnocchis dorés à la poêle, enrobés d''une sauce à la fourme d''Ambert, avec des dés de poire poêlés et des noix. Prêt en 20 minutes.', 'Se garde 1 jour au réfrigérateur ; réchauffer à la poêle.', 2, 5, 15, array['plat', 'poele']::text[]),
  ('salade-tiede-lentilles-saint-nectaire-lardons', 'Salade tiède de lentilles, saint-nectaire et lardons', 'Des lentilles vertes tièdes à la vinaigrette moutardée, avec des lardons grillés, des dés de saint-nectaire, de l''oignon rouge et de la mâche.', 'Se garde 3 jours au réfrigérateur ; ajouter la mâche au dernier moment.', 2, 10, 25, array['salade', 'plat', 'lunch-box', 'economique']::text[]),
  ('burrata-butternut-rotie-lentilles', 'Burrata, butternut rôtie et lentilles', 'Des cubes de butternut rôtis au four, servis sur des lentilles vertes tièdes et coiffés d''une burrata crémeuse, avec un filet d''huile d''olive et des graines de sésame.', 'Lentilles et butternut se gardent 3 jours au réfrigérateur ; ajouter la burrata au moment de servir.', 2, 10, 30, array['plat', 'four']::text[]),
  ('pates-cacio-e-pepe-pecorino', 'Pâtes au pecorino et au poivre', 'Des pâtes liées d''une sauce crémeuse au pecorino râpé et au poivre noir concassé, faite seulement avec l''eau de cuisson. Trois ingrédients, 15 minutes.', 'À manger tout de suite : la sauce ne se réchauffe pas bien.', 2, 5, 10, array['plat', 'express', 'economique']::text[]),
  ('pates-mascarpone-citron-saumon-fume', 'Pâtes au mascarpone, citron et saumon fumé', 'Des pâtes enrobées d''une sauce minute au mascarpone et au zeste de citron, avec des lanières de saumon fumé et des épinards. Prêt en 15 minutes.', 'Se garde 1 jour au réfrigérateur ; à manger de préférence tout de suite.', 2, 5, 10, array['plat', 'express']::text[])
) as v(slug, title, description, storage, servings, prep, cook, tags);

