insert into public.recipe_steps (recipe_id, position, instruction)
select r.id, v.pos, v.instruction
from (values
  ('raclette-au-four-pommes-de-terre-jambon-cru', 1, 'Cuire les pommes de terre entières 20 minutes dans une casserole d''eau salée : la pointe d''un couteau doit s''enfoncer sans résistance.'),
  ('raclette-au-four-pommes-de-terre-jambon-cru', 2, 'Préchauffer le four en position gril à 220 °C.'),
  ('raclette-au-four-pommes-de-terre-jambon-cru', 3, 'Couper les pommes de terre en deux et les ranger côté coupé vers le haut dans un plat.'),
  ('raclette-au-four-pommes-de-terre-jambon-cru', 4, 'Couvrir de tranches de raclette, poivrer et passer 6 à 8 minutes sous le gril : le fromage doit fondre et commencer à dorer.'),
  ('raclette-au-four-pommes-de-terre-jambon-cru', 5, 'Servir aussitôt avec le jambon cru, les cornichons et la mâche.'),
  ('tartiflette-reblochon-lardons', 1, 'Cuire les pommes de terre épluchées 15 minutes dans une casserole d''eau salée : elles doivent rester un peu fermes. Les couper en rondelles épaisses.'),
  ('tartiflette-reblochon-lardons', 2, 'Préchauffer le four à 200 °C.'),
  ('tartiflette-reblochon-lardons', 3, 'Faire revenir les lardons et les oignons émincés 8 minutes dans une poêle à feu moyen, puis déglacer au vin blanc.'),
  ('tartiflette-reblochon-lardons', 4, 'Mélanger les pommes de terre, les lardons, les oignons et la crème dans un plat, et poivrer.'),
  ('tartiflette-reblochon-lardons', 5, 'Couper le reblochon en deux dans l''épaisseur et le poser croûte vers le haut sur les pommes de terre.'),
  ('tartiflette-reblochon-lardons', 6, 'Cuire 25 minutes au four : le fromage doit être fondu et doré. Servir avec la mâche.'),
  ('mont-d-or-chaud-pommes-de-terre', 1, 'Préchauffer le four à 200 °C et cuire les pommes de terre 20 minutes dans une casserole d''eau salée.'),
  ('mont-d-or-chaud-pommes-de-terre', 2, 'Retirer le couvercle de la boîte de mont d''or, l''emballer de papier aluminium sur les côtés et piquer le dessus de lamelles d''ail.'),
  ('mont-d-or-chaud-pommes-de-terre', 3, 'Verser le vin blanc sur le fromage et cuire 20 minutes au four : le cœur doit être coulant.'),
  ('mont-d-or-chaud-pommes-de-terre', 4, 'Servir le mont d''or dans sa boîte, avec les pommes de terre, le jambon cru, la mâche et du poivre.'),
  ('truffade-cantal-lardons', 1, 'Éplucher les pommes de terre et les couper en fines rondelles, hacher l''ail et couper le cantal en lamelles.'),
  ('truffade-cantal-lardons', 2, 'Faire revenir les lardons 3 minutes dans l''huile, dans une grande poêle à feu moyen.'),
  ('truffade-cantal-lardons', 3, 'Ajouter les pommes de terre et les cuire 20 minutes à couvert en remuant souvent : elles doivent être tendres et dorées.'),
  ('truffade-cantal-lardons', 4, 'Ajouter l''ail et le cantal, et mélanger 5 minutes à feu doux jusqu''à ce que le fromage fonde et file.'),
  ('truffade-cantal-lardons', 5, 'Poivrer et servir aussitôt avec le persil et la mâche.'),
  ('risotto-champignons-beaufort', 1, 'Délayer le bouillon dans de l''eau chaude et le garder frémissant, émincer l''oignon et les champignons, râper le beaufort.'),
  ('risotto-champignons-beaufort', 2, 'Faire revenir l''oignon et les champignons 5 minutes dans le beurre, dans une sauteuse à feu moyen.'),
  ('risotto-champignons-beaufort', 3, 'Ajouter le riz et le nacrer 2 minutes en remuant, puis verser le vin blanc et le laisser s''évaporer.'),
  ('risotto-champignons-beaufort', 4, 'Ajouter le bouillon louche par louche pendant 18 minutes, en attendant qu''il soit absorbé à chaque fois : le riz doit être crémeux et encore un peu ferme.'),
  ('risotto-champignons-beaufort', 5, 'Hors du feu, incorporer le beaufort, poivrer, couvrir 2 minutes et servir avec le persil.'),
  ('gratin-chou-fleur-gruyere-jambon', 1, 'Préchauffer le four à 200 °C et cuire le chou-fleur en bouquets 8 minutes à l''eau bouillante salée, puis l''égoutter.'),
  ('gratin-chou-fleur-gruyere-jambon', 2, 'Faire fondre le beurre dans une casserole, ajouter la farine et remuer 1 minute, puis verser le lait petit à petit en fouettant.'),
  ('gratin-chou-fleur-gruyere-jambon', 3, 'Cuire la béchamel 4 minutes à feu doux en remuant : elle doit napper la cuillère. Ajouter la moitié du gruyère râpé, la muscade et le poivre.'),
  ('gratin-chou-fleur-gruyere-jambon', 4, 'Ranger le chou-fleur et le jambon en dés dans un plat, napper de béchamel et parsemer du reste de gruyère.'),
  ('gratin-chou-fleur-gruyere-jambon', 5, 'Cuire 20 minutes au four : le dessus doit être bien doré.'),
  ('gratin-poireaux-mimolette-jambon', 1, 'Préchauffer le four à 200 °C. Couper les poireaux en tronçons de la longueur d''une tranche de jambon et les cuire 10 minutes à l''eau bouillante salée, puis les égoutter.'),
  ('gratin-poireaux-mimolette-jambon', 2, 'Faire fondre le beurre dans une casserole, ajouter la farine 1 minute, puis verser le lait en fouettant et cuire 4 minutes jusqu''à ce que la sauce épaississe.'),
  ('gratin-poireaux-mimolette-jambon', 3, 'Ajouter la moitié de la mimolette râpée à la sauce et poivrer.'),
  ('gratin-poireaux-mimolette-jambon', 4, 'Rouler les poireaux dans le jambon, les ranger dans un plat, napper de sauce et parsemer du reste de mimolette.'),
  ('gratin-poireaux-mimolette-jambon', 5, 'Cuire 15 minutes au four : le dessus doit être doré.'),
  ('camembert-roti-pommes-de-terre-jambon-cru', 1, 'Préchauffer le four à 200 °C et cuire les pommes de terre entières 20 minutes dans une casserole d''eau salée.'),
  ('camembert-roti-pommes-de-terre-jambon-cru', 2, 'Retirer l''emballage du camembert, le remettre dans sa boîte en bois, entailler le dessus en croisillons et y piquer l''ail en lamelles et le thym.'),
  ('camembert-roti-pommes-de-terre-jambon-cru', 3, 'Arroser d''un filet d''huile et cuire 15 minutes au four : le cœur doit être coulant.'),
  ('camembert-roti-pommes-de-terre-jambon-cru', 4, 'Servir le camembert avec les pommes de terre, le jambon cru et la mâche assaisonnée du reste d''huile.'),
  ('flamiche-maroilles-poireaux', 1, 'Préchauffer le four à 190 °C et foncer un moule à tarte avec la pâte.'),
  ('flamiche-maroilles-poireaux', 2, 'Émincer les poireaux et les faire fondre 10 minutes dans le beurre, dans une poêle à feu doux : ils doivent être tendres sans colorer.'),
  ('flamiche-maroilles-poireaux', 3, 'Fouetter les œufs avec la crème et du poivre.'),
  ('flamiche-maroilles-poireaux', 4, 'Étaler les poireaux sur la pâte, verser l''appareil et répartir le maroilles en tranches, croûte comprise.'),
  ('flamiche-maroilles-poireaux', 5, 'Cuire 35 minutes au four : la flamiche doit être dorée et prise. Servir tiède avec la salade.'),
  ('pommes-de-terre-farcies-munster-jambon', 1, 'Préchauffer le four à 200 °C et cuire les pommes de terre entières 25 minutes dans une casserole d''eau salée : elles doivent être tendres.'),
  ('pommes-de-terre-farcies-munster-jambon', 2, 'Couper les pommes de terre en deux, les évider à la cuillère en gardant une fine épaisseur de chair.'),
  ('pommes-de-terre-farcies-munster-jambon', 3, 'Écraser la chair avec la crème, le jambon en dés, le cumin et du poivre, puis en garnir les pommes de terre.'),
  ('pommes-de-terre-farcies-munster-jambon', 4, 'Couvrir de lamelles de munster et cuire 15 minutes au four : le fromage doit être fondu et doré.'),
  ('pommes-de-terre-farcies-munster-jambon', 5, 'Servir avec la mâche.'),
  ('feuillete-brie-poireaux', 1, 'Préchauffer le four à 200 °C et dérouler la pâte sur une plaque, en gardant le papier de cuisson.'),
  ('feuillete-brie-poireaux', 2, 'Émincer les poireaux et les faire fondre 10 minutes dans le beurre, dans une poêle à feu doux.'),
  ('feuillete-brie-poireaux', 3, 'Battre les œufs avec la crème et du poivre, puis mélanger aux poireaux.'),
  ('feuillete-brie-poireaux', 4, 'Étaler la garniture sur la pâte en laissant un bord libre, puis poser le brie en tranches.'),
  ('feuillete-brie-poireaux', 5, 'Cuire 25 minutes au four : la pâte doit être dorée et croustillante. Servir avec la mâche.'),
  ('pates-gorgonzola-epinards-noix', 1, 'Cuire les pâtes dans une grande casserole d''eau bouillante salée selon le temps du paquet, puis les égoutter en gardant un fond d''eau de cuisson.'),
  ('pates-gorgonzola-epinards-noix', 2, 'Faire fondre le gorgonzola dans la crème 3 minutes dans une sauteuse à feu doux, en remuant jusqu''à obtenir une sauce lisse.'),
  ('pates-gorgonzola-epinards-noix', 3, 'Ajouter les épinards et les laisser tomber 2 minutes.'),
  ('pates-gorgonzola-epinards-noix', 4, 'Ajouter les pâtes et un peu d''eau de cuisson, mélanger, puis servir avec les noix concassées et du poivre.'),
  ('salade-endives-poulet-roquefort-noix', 1, 'Couper le poulet en lanières et le dorer 7 minutes dans une poêle avec un filet d''huile : il doit être cuit à cœur. Le laisser tiédir.'),
  ('salade-endives-poulet-roquefort-noix', 2, 'Émincer les endives, couper la poire en lamelles et émietter le roquefort.'),
  ('salade-endives-poulet-roquefort-noix', 3, 'Fouetter la moutarde, le vinaigre, le reste de l''huile et du poivre.'),
  ('salade-endives-poulet-roquefort-noix', 4, 'Mélanger les endives, la poire, le poulet et la vinaigrette, puis parsemer de roquefort et de noix concassées.'),
  ('gnocchis-fourme-ambert-poire-noix', 1, 'Couper la poire en dés et la poêler 3 minutes dans le beurre à feu moyen, puis la réserver.'),
  ('gnocchis-fourme-ambert-poire-noix', 2, 'Dorer les gnocchis 8 minutes dans la même poêle à feu moyen, en remuant souvent : ils doivent être croustillants à l''extérieur.'),
  ('gnocchis-fourme-ambert-poire-noix', 3, 'Ajouter la crème et la fourme coupée en dés, et remuer 2 minutes à feu doux jusqu''à ce que le fromage fonde.'),
  ('gnocchis-fourme-ambert-poire-noix', 4, 'Ajouter la poire, poivrer et servir avec les noix concassées.'),
  ('salade-tiede-lentilles-saint-nectaire-lardons', 1, 'Cuire les lentilles 20 minutes dans une casserole d''eau non salée : elles doivent être tendres mais entières. Les égoutter.'),
  ('salade-tiede-lentilles-saint-nectaire-lardons', 2, 'Dorer les lardons 5 minutes à sec dans une poêle à feu moyen.'),
  ('salade-tiede-lentilles-saint-nectaire-lardons', 3, 'Fouetter la moutarde, le vinaigre, l''huile et du poivre, et émincer finement l''oignon rouge.'),
  ('salade-tiede-lentilles-saint-nectaire-lardons', 4, 'Mélanger les lentilles tièdes avec la vinaigrette, l''oignon et les lardons.'),
  ('salade-tiede-lentilles-saint-nectaire-lardons', 5, 'Ajouter le saint-nectaire en dés et la mâche au moment de servir.'),
  ('burrata-butternut-rotie-lentilles', 1, 'Préchauffer le four à 200 °C. Éplucher la butternut, la couper en cubes et la rôtir 30 minutes avec la moitié de l''huile : elle doit être tendre et dorée.'),
  ('burrata-butternut-rotie-lentilles', 2, 'Pendant ce temps, cuire les lentilles 20 minutes dans une casserole d''eau non salée, puis les égoutter.'),
  ('burrata-butternut-rotie-lentilles', 3, 'Assaisonner les lentilles avec le reste de l''huile, le vinaigre balsamique et du poivre.'),
  ('burrata-butternut-rotie-lentilles', 4, 'Répartir les lentilles et la butternut dans les assiettes, poser la burrata au centre, l''ouvrir et parsemer de sésame.'),
  ('pates-cacio-e-pepe-pecorino', 1, 'Cuire les spaghetti dans une casserole d''eau bouillante peu salée selon le temps du paquet, en gardant un grand bol d''eau de cuisson.'),
  ('pates-cacio-e-pepe-pecorino', 2, 'Râper finement le pecorino et concasser le poivre, puis le torréfier 1 minute à sec dans une grande poêle.'),
  ('pates-cacio-e-pepe-pecorino', 3, 'Mélanger le pecorino avec quelques cuillères d''eau de cuisson tiède jusqu''à obtenir une crème lisse.'),
  ('pates-cacio-e-pepe-pecorino', 4, 'Mettre les pâtes égouttées et le beurre dans la poêle hors du feu, ajouter la crème de pecorino et mélanger vivement en ajoutant de l''eau de cuisson jusqu''à ce que la sauce nappe.'),
  ('pates-mascarpone-citron-saumon-fume', 1, 'Cuire les pâtes dans une grande casserole d''eau bouillante salée selon le temps du paquet, puis les égoutter en gardant un fond d''eau de cuisson.'),
  ('pates-mascarpone-citron-saumon-fume', 2, 'Râper le zeste du citron, presser son jus et couper le saumon en lanières.'),
  ('pates-mascarpone-citron-saumon-fume', 3, 'Faire fondre le mascarpone avec le zeste et un peu d''eau de cuisson 2 minutes dans une sauteuse à feu doux, puis ajouter les épinards 1 minute.'),
  ('pates-mascarpone-citron-saumon-fume', 4, 'Ajouter les pâtes, le saumon et le jus de citron, mélanger hors du feu et servir avec le poivre et la ciboulette.')
) as v(recipe, pos, instruction)
join public.recipes r on r.slug = v.recipe;

-- Garde-fou : une jointure silencieusement vide (slug introuvable) fait échouer la migration.
do $$
begin
  if (select count(*) from public.recipe_ingredients ri join public.recipes r on r.id = ri.recipe_id
      where r.slug in ('raclette-au-four-pommes-de-terre-jambon-cru', 'tartiflette-reblochon-lardons', 'mont-d-or-chaud-pommes-de-terre', 'truffade-cantal-lardons', 'risotto-champignons-beaufort', 'gratin-chou-fleur-gruyere-jambon', 'gratin-poireaux-mimolette-jambon', 'camembert-roti-pommes-de-terre-jambon-cru', 'flamiche-maroilles-poireaux', 'pommes-de-terre-farcies-munster-jambon', 'feuillete-brie-poireaux', 'pates-gorgonzola-epinards-noix', 'salade-endives-poulet-roquefort-noix', 'gnocchis-fourme-ambert-poire-noix', 'salade-tiede-lentilles-saint-nectaire-lardons', 'burrata-butternut-rotie-lentilles', 'pates-cacio-e-pepe-pecorino', 'pates-mascarpone-citron-saumon-fume')) <> 132 then
    raise exception 'Lignes d''ingrédients manquantes dans le vingt et unième lot de recettes.';
  end if;
end;
$$;
